static boolean verifyNoLeaks(ExecutorService pool, ThreadLocal<String> tl, int taskCount) throws Exception {
    AtomicBoolean wyciekWykryty = new AtomicBoolean(false);
    List<Future<?>> futures = new ArrayList<>();
    for (int i=0;i<taskCount;i++) { int id=i; futures.add(pool.submit(() -> { if (tl.get() != null) wyciekWykryty.set(true); try { tl.set("val-"+id); } finally { tl.remove(); } })); }
    for (Future<?> f : futures) f.get();
    return !wyciekWykryty.get();
}
ExecutorService pool = Executors.newFixedThreadPool(1);
ThreadLocal<String> tl = new ThreadLocal<>();
System.out.println(verifyNoLeaks(pool, tl, 10));
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

