class SecurityContext {
    private static final ThreadLocal<Map<String,Object>> CONTEXT = ThreadLocal.withInitial(HashMap::new);
    static void login(String user, List<String> roles) { CONTEXT.get().put("user", user); CONTEXT.get().put("roles", roles); CONTEXT.get().put("authenticated", true); }
    static void logout() { CONTEXT.remove(); }
    static boolean isAuthenticated() { return Boolean.TRUE.equals(CONTEXT.get().get("authenticated")); }
    static boolean hasRole(String role) { return isAuthenticated() && ((List<String>) CONTEXT.get().getOrDefault("roles", List.of())).contains(role); }
}
ExecutorService pool = Executors.newFixedThreadPool(3);
for (int i=1;i<=5;i++) { int id=i; pool.submit(() -> { try { if (id%2==0) SecurityContext.login("user"+id, List.of("USER")); System.out.println("zadanie-"+id+": authenticated="+SecurityContext.isAuthenticated()); } finally { SecurityContext.logout(); } }); }
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

class PerThreadObjectPool<T> {
    private final ThreadLocal<Deque<T>> pool;
    private final Supplier<T> factory;
    PerThreadObjectPool(Supplier<T> factory) { this.factory = factory; this.pool = ThreadLocal.withInitial(ArrayDeque::new); }
    T borrow() { T obj = pool.get().poll(); return obj != null ? obj : factory.get(); }
    void release(T obj) { pool.get().offer(obj); }
}
PerThreadObjectPool<StringBuilder> pula = new PerThreadObjectPool<>(StringBuilder::new);
for (int i=1;i<=5;i++) { int id=i; Thread t = new Thread(() -> { for (int j=0;j<10;j++) { StringBuilder sb = pula.borrow(); sb.append("praca"); pula.release(sb); sb.setLength(0); } System.out.println("watek-"+id+" zakonczony"); }); t.start(); t.join(2000); }

