class MiniMDC {
    private static final ThreadLocal<Map<String,String>> CONTEXT = ThreadLocal.withInitial(HashMap::new);
    static void put(String k, String v) { CONTEXT.get().put(k, v); }
    static String get(String k) { return CONTEXT.get().get(k); }
    static void clear() { CONTEXT.remove(); }
}
static Runnable withMdcContext(Map<String,String> context, Runnable task) {
    return () -> { context.forEach(MiniMDC::put); try { task.run(); } finally { MiniMDC.clear(); } };
}
