pool.submit(withMdcContext(kontekstZglaszajacy, () -> System.out.println("traceId w puli: "+MiniMDC.get("traceId"))));
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);

ThreadLocal<Map<String,Object>> kontekstZadania = ThreadLocal.withInitial(HashMap::new);
static Runnable wrapZadanie(int requestId, Runnable praca) {
    return () -> {
        kontekstZadania.get().put("requestId", requestId);
        kontekstZadania.get().put("startTime", System.currentTimeMillis());
        try { praca.run(); }
        finally { kontekstZadania.remove(); }
    };
}
